CREATE TABLE `campeonatos` (
  `campeonato_id` int NOT NULL,
  `nome` varchar(255) DEFAULT NULL,
  `nome_popular` varchar(255) DEFAULT NULL,
  `slug` varchar(255) DEFAULT NULL,
  `tipo` varchar(50) DEFAULT NULL,
  `status` varchar(50) DEFAULT NULL,
  `logo` varchar(255) DEFAULT NULL,
  `regiao` varchar(50) DEFAULT NULL,
  `edicao_id` int DEFAULT NULL,
  `temporada` varchar(10) DEFAULT NULL,
  `nome_edicao` varchar(255) DEFAULT NULL,
  `nome_edicao_popular` varchar(255) DEFAULT NULL,
  `slug_edicao` varchar(255) DEFAULT NULL,
  `fase_id` int DEFAULT NULL,
  `fase_nome` varchar(255) DEFAULT NULL,
  `fase_slug` varchar(255) DEFAULT NULL,
  `fase_tipo` varchar(50) DEFAULT NULL,
  `rodada_atual` int DEFAULT NULL,
  `rodada_status` varchar(50) DEFAULT NULL,
  `atualizado_em` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`campeonato_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
