DROP TABLE IF EXISTS `classificacao`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `classificacao` (
  `id` int NOT NULL AUTO_INCREMENT,
  `campeonato_id` int NOT NULL,
  `tipo_competicao` varchar(100) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `fase` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `grupo` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `posicao` int DEFAULT NULL,
  `pontos` int DEFAULT NULL,
  `time_id` int DEFAULT NULL,
  `nome_popular` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `sigla` varchar(10) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `escudo` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `jogos` int DEFAULT NULL,
  `vitorias` int DEFAULT NULL,
  `empates` int DEFAULT NULL,
  `derrotas` int DEFAULT NULL,
  `gols_pro` int DEFAULT NULL,
  `gols_contra` int DEFAULT NULL,
  `saldo_gols` int DEFAULT NULL,
  `aproveitamento` decimal(5,2) DEFAULT NULL,
  `variacao_posicao` int DEFAULT NULL,
  `ultimos_jogos` mediumtext COLLATE utf8mb4_general_ci,
  `atualizado_em` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_campeonato_time` (`campeonato_id`,`time_id`),
  UNIQUE KEY `uniq_class` (`campeonato_id`,`tipo_competicao`,`grupo`,`posicao`),
  KEY `idx_campeonato` (`campeonato_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2061 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

