DROP TABLE IF EXISTS `extrato_movimentacao`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `extrato_movimentacao` (
  `id` int NOT NULL AUTO_INCREMENT,
  `usuario_id` int NOT NULL,
  `tipo` enum('deposito','saque','palpite_debitado','premiacao_creditada') COLLATE utf8mb4_general_ci NOT NULL,
  `valor` decimal(15,2) NOT NULL,
  `saldo_anterior` decimal(15,2) NOT NULL,
  `saldo_novo` decimal(15,2) NOT NULL,
  `descricao` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `referencia_id` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `referencia_tipo` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `status` enum('pendente','confirmado','cancelado') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'confirmado',
  `criado_em` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_usuario_id` (`usuario_id`),
  KEY `idx_tipo` (`tipo`),
  KEY `idx_criado_em` (`criado_em`),
  KEY `idx_status` (`status`),
  CONSTRAINT `extrato_movimentacao_ibfk_1` FOREIGN KEY (`usuario_id`) REFERENCES `usuarios` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=94 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
