  `tempo_alerta` int NOT NULL COMMENT '60, 30, 15 ou 5 minutos',
  `notification_id` bigint DEFAULT NULL,
  `data_envio` datetime DEFAULT CURRENT_TIMESTAMP,
  `data_agendada` datetime DEFAULT NULL COMMENT 'Quando a notificação deve disparar',
  `status` enum('agendada','enviada','expirada','cancelada') COLLATE utf8mb4_unicode_ci DEFAULT 'agendada',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_rodada_tempo_alerta` (`rodada_id`,`tempo_alerta`),
  UNIQUE KEY `notification_id` (`notification_id`),
  KEY `idx_rodada_tempo` (`rodada_id`,`tempo_alerta`),
  KEY `idx_data_envio` (`data_envio`),
  KEY `idx_status` (`status`),
  CONSTRAINT `notificacoes_enviadas_ibfk_1` FOREIGN KEY (`rodada_id`) REFERENCES `rodadas` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
