DROP TABLE IF EXISTS `ranking_pontos_partida`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ranking_pontos_partida` (
  `id` int NOT NULL AUTO_INCREMENT,
  `grupo_id` int NOT NULL,
  `campeonato_id` int NOT NULL,
  `rodada` int NOT NULL,
  `partida_id` bigint NOT NULL,
  `usuario_id` int NOT NULL,
  `pontos` decimal(4,2) NOT NULL,
  `acerto_exato` tinyint(1) DEFAULT '0',
  `vencedor_correto` tinyint(1) DEFAULT '0',
  `gols_casa_corretos` tinyint(1) DEFAULT '0',
  `gols_fora_corretos` tinyint(1) DEFAULT '0',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_user_partida` (`usuario_id`,`partida_id`,`rodada`,`campeonato_id`,`grupo_id`),
  KEY `idx_rodada_grupo` (`rodada`,`grupo_id`),
  KEY `idx_grupo_campeonato` (`grupo_id`,`campeonato_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2227 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
